using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatClientBuilder =>
    chatClientBuilder.UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();
var loggerFactory = host.Services.GetRequiredService<ILoggerFactory>();

var tools = new AITool[]
{
    AIFunctionFactory.Create(researchTools.SearchWebAsync),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
            Instructions = """
                You are a research assistant. When given a topic:
                1. Search the web for relevant information using different search queries.
                2. Save important findings as notes using the note-taking tool.
                3. After gathering enough information, retrieve your notes and provide a
                   well-structured summary with key findings and sources.
                Be thorough but concise. Always cite your sources.
                """,
        },
    },
    loggerFactory);

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var input = Console.ReadLine();

    if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    researchTools.ClearNotes();

    Console.WriteLine("\nResearching...\n");

    var session = await agent.CreateSessionAsync();
    var response = await agent.RunAsync(
        $"Research the following topic and provide a summary: {input}",
        session,
        new ChatClientAgentRunOptions
        {
            ChatOptions = new ChatOptions { MaxOutputTokens = 4096 },
        });

    Console.WriteLine(response);
}

Console.WriteLine("Goodbye!");

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();
    private readonly ILogger<ResearchTools> _logger;

    public ResearchTools(ILogger<ResearchTools> logger) => _logger = logger;

    [Description("Search the web for information on a query. Returns a list of search results with titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        _logger.LogDebug("Searching web for: {Query}", query);

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var request = new HttpRequestMessage(HttpMethod.Get,
                $"https://html.duckduckgo.com/html/?q={encoded}");
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync(cancellationToken);

            var results = ParseSearchResults(html);
            if (results.Count == 0)
            {
                return $"No results found for '{query}'.";
            }

            return string.Join("\n\n", results.Select((r, i) =>
                $"[{i + 1}] {r.Title}\n    URL: {r.Url}\n    {r.Snippet}"));
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Web search failed for query: {Query}", query);
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("The note content to save")] string note,
        [Description("The source URL or reference for this note")] string source)
    {
        _notes.Add($"[Source: {source}] {note}");
        _logger.LogDebug("Note saved ({Count} total)", _notes.Count);
        return $"Note saved. Total notes: {_notes.Count}";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return string.Join("\n\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }

    public void ClearNotes() => _notes.Clear();

    private static List<SearchResult> ParseSearchResults(string html)
    {
        var results = new List<SearchResult>();
        var span = html.AsSpan();

        const string resultClass = "result__a";
        const string snippetClass = "result__snippet";

        int pos = 0;
        while (results.Count < 5)
        {
            int linkStart = html.IndexOf($"class=\"{resultClass}\"", pos, StringComparison.Ordinal);
            if (linkStart < 0) break;

            var href = ExtractAttribute(html, linkStart, "href");
            var title = ExtractInnerText(html, linkStart);

            int snippetStart = html.IndexOf($"class=\"{snippetClass}\"", linkStart, StringComparison.Ordinal);
            var snippet = snippetStart >= 0 ? ExtractInnerText(html, snippetStart) : "";

            if (!string.IsNullOrWhiteSpace(title))
            {
                results.Add(new SearchResult(title.Trim(), href?.Trim() ?? "", snippet.Trim()));
            }

            pos = Math.Max(linkStart + 1, snippetStart > 0 ? snippetStart + 1 : linkStart + 1);
        }

        return results;
    }

    private static string? ExtractAttribute(string html, int startFrom, string attribute)
    {
        var marker = $"{attribute}=\"";
        int attrStart = html.IndexOf(marker, startFrom, StringComparison.Ordinal);
        if (attrStart < 0) return null;

        attrStart += marker.Length;
        int attrEnd = html.IndexOf('"', attrStart);
        return attrEnd > attrStart ? html[attrStart..attrEnd] : null;
    }

    private static string ExtractInnerText(string html, int startFrom)
    {
        int tagEnd = html.IndexOf('>', startFrom);
        if (tagEnd < 0) return "";

        int contentStart = tagEnd + 1;
        int closeTag = html.IndexOf('<', contentStart);
        if (closeTag < 0) return "";

        return System.Net.WebUtility.HtmlDecode(html[contentStart..closeTag]) ?? "";
    }

    private sealed record SearchResult(string Title, string Url, string Snippet);
}

